typedef float rational_t;

extern "C" float sqrtf(float);
#define __fsqrt sqrtf

template <class T>
inline const T& max(const T& a, const T& b)
{
  return a < b ? b : a;
}

class vector3d
{
public:
  typedef rational_t T;
  T x,y,z;

  inline vector3d() {}
  inline vector3d(const vector3d& v) { x = v.x; y = v.y; z = v.z; }
  inline vector3d& operator-=(const vector3d& v) { x -= v.x; y -= v.y; z -= v.z; return *this; }
  inline T xz_length2() const { return x*x + z*z; }
};

class po
{
public:
  vector3d non_affine_slow_xform(const vector3d& source_vector) const;
};

class hw_rasta_vert
{
public:
  vector3d xyz;
  char released_layout[48];
};

class vr_pmesh
{
  char released_layout0[24];
protected:
  hw_rasta_vert *xverts;
  char released_layout1[12];
  int num_wedges;
  char released_layout2[76];
  vector3d center;
public:
  inline int get_num_wedges() const { return num_wedges; }
  virtual rational_t compute_xz_radius_rel_center( const po& xform );
};

rational_t vr_pmesh::compute_xz_radius_rel_center( const po& xform )
{
#if defined(TARGET_PC)  || XBOX_USE_PMESH_STUFF
  if (optimized_verts)
    return radius * xform.get_scale();
#endif

  rational_t rad2 = 0.0f;
  int i;
  vector3d ctr = xform.non_affine_slow_xform( center );
  for ( i=get_num_wedges(); --i>=0; )
  {
    vector3d v = xform.non_affine_slow_xform( xverts[i].xyz );
    v -= ctr;
    rad2 = max( v.xz_length2(), rad2 );
  }
  return __fsqrt(rad2);
}
